INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(30811, 'James 2:2', 'James', 2, 2, 'فرض کړئ یو سړی چې د سرو زرو ګوته یې په لاس وي او ښکلي کالي یې اغوستي وي او ستاسو غونډې ته راشي او یو غریب سړی په زړو کالیو کې راشي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_2.mp3', '', 1761754199, 1761754199),
(30812, 'James 2:3', 'James', 2, 3, 'او تاسو د هغه سړي درناوی وکړئ چې ښکلي کالي یې اغوستي دي او ورته ووایئ: «مهرباني وکړئ دلته په دې ښه ځای کې کښېنئ» او هغه غریب سړي ته ووایئ: «هلته ودرېږه یا دلته په ځمکه باندې کښېنه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_3.mp3', '', 1761754199, 1761754199),
(30813, 'James 2:4', 'James', 2, 4, 'ایا تاسو په خپل منځ کې د تبعیض څخه کار وانخیست او ایا د بدو خیالونو له مخې مو قضاوت ونه کړ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_4.mp3', '', 1761754199, 1761754199),
(30814, 'James 2:5', 'James', 2, 5, 'ای زما ګرانو خویندو او ورونو! واورئ، ایا خدای د دې نړۍ غریبان نه دي غوره کړي چې په ایمان کې شتمن وي او د هغې پاچاهۍ وارثان وي چې خدای د هغو خلکو سره وعده کړې ده چې ورسره مینه کوي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_5.mp3', '', 1761754199, 1761754199),
(30815, 'James 2:6', 'James', 2, 6, 'خو تاسو د غریب سړي سپکاوی وکړ. ایا شتمن خلک په تاسو باندې ظلم نه کوي او تاسو محکمو ته نه راکاږي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_6.mp3', '', 1761754199, 1761754199),
(30816, 'James 2:7', 'James', 2, 7, 'ایا هغوی د مسیح نېک نوم چې خدای په تاسو باندې ایښی دی، نه بدناموي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_7.mp3', '', 1761754199, 1761754199),
(30817, 'James 2:8', 'James', 2, 8, 'که چېرې تاسو په رښتیا سره د څښتن د شریعت په شاهانه حکم باندې عمل وکړئ چې د خدای په کلام کې یې یادونه شوې ده چې وایي: «د خپل ګاونډي سره د خپل ځان په شان مینه کوه» نو ښه کار کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_8.mp3', '', 1761754199, 1761754199),
(30818, 'James 2:9', 'James', 2, 9, 'خو که چېرې تاسو د کوم چا طرفداري کوئ نو ګناه کوئ او شریعت تاسو د قانون ماتوونکو په توګه محکوموي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_9.mp3', '', 1761754199, 1761754199),
(30819, 'James 2:10', 'James', 2, 10, 'ځکه که چېرې څوک د شریعت په ټولو حکمونو عمل وکړي خو یو حکم یې مات کړي نو هغه د ټول شریعت په ماتولو ګناهکار شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_10.mp3', '', 1761754199, 1761754199),
(30820, 'James 2:11', 'James', 2, 11, 'ځکه چا چې ویلي دي: «زنا مه کوه.» نو دا یې هم ویلي دي: «قتل مه کوه.» که ته زنا نه کوې خو قتل وکړې، نو بیاهم ته د شریعت ماتوونکی شوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_11.mp3', '', 1761754199, 1761754199),
(30821, 'James 2:12', 'James', 2, 12, 'نو د هغو خلکو په شان خبرې او عمل وکړئ چې د هغه شریعت له مخې به ورباندې قضاوت کیږي چې مونږ ته ازادي راکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_12.mp3', '', 1761754199, 1761754199),
(30822, 'James 2:13', 'James', 2, 13, 'ځکه چې د قضاوت په وخت کې به خدای په هغه چا باندې رحم ونه کړي چې په نورو باندې یې رحم نه دی کړی. خو بیاهم رحم په قضاوت باندې بریالی دی. بې له عمل نه ایمان مړ دی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_13.mp3', '', 1761754199, 1761754199),
(30823, 'James 2:14', 'James', 2, 14, 'ای زما خویندو او ورونو! که څوک ووایي چې زه ایمان لرم خو عمل نه کوي نو ګټه یې څه ده؟ ایا داسې ایمان هغه ته خلاصون ورکولای شي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_14.mp3', '', 1761754199, 1761754199),
(30824, 'James 2:15', 'James', 2, 15, 'فرض کړئ تاسو ووینئ چې یو ورور یا خور کالیو او خوړو ته اړتیا لري،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_15.mp3', '', 1761754199, 1761754199),
(30825, 'James 2:16', 'James', 2, 16, 'او ستاسو څخه یو څوک هغه ته ووایي: «په خیر لاړ شه او تود او موړ اوسه.» خو چې کومو شیانو ته اړتیا لري هغه ورته ورنه کړئ نو څه ګټه به ولري؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_16.mp3', '', 1761754199, 1761754199),
(30826, 'James 2:17', 'James', 2, 17, 'نو په همدې ډول که چېرې د ایمان سره عمل نه وي نو هغه ایمان مړ دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_17.mp3', '', 1761754199, 1761754199),
(30827, 'James 2:18', 'James', 2, 18, 'خو کېدای شي چې څوک ووایي: «ته ایمان لرې او زه نېک کارونه کوم. ته دې خپل ایمان بې له عمله ماته وښایه او زه به خپل ایمان د خپلو عملونو په وسیله تاته دروښایم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_18.mp3', '', 1761754199, 1761754199),
(30828, 'James 2:19', 'James', 2, 19, 'ته په دې باور لرې چې خدای یو دی نو ډېره ښه ده. شیطان او پېریان هم په دې باور لري او له وېرې رپیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_19.mp3', '', 1761754199, 1761754199),
(30829, 'James 2:20', 'James', 2, 20, 'ای ناپوهه سړیه! ایا په دې نه پوهېږې چې ایمان بې له عمل نه بې‌ګټې دی؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_20.mp3', '', 1761754199, 1761754199),
(30830, 'James 2:21', 'James', 2, 21, 'کله چې زمونږ نیکه ابراهیم خپل زوی اسحاق د قربانۍ په ځای کې خدای ته وړاندې کړ نو ایا هغه په دې عمل سره د خدای له خوا نېک ونه ګڼل شو؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_21.mp3', '', 1761754199, 1761754199),
(30831, 'James 2:22', 'James', 2, 22, 'تاسو ګورئ چې د هغه ایمان او عمل په ګډه سره کار وکړ او په عمل سره د هغه ایمان کامل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_22.mp3', '', 1761754199, 1761754199),
(30832, 'James 2:23', 'James', 2, 23, 'په دې ډول د خدای د کلام هغه وینا رښتیا شوه چې وایي: ابراهیم په خدای ایمان راوړ او په دې باندې هغه عادل وګڼل شو. او هغه د خدای دوست وبلل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_23.mp3', '', 1761754199, 1761754199),
(30833, 'James 2:24', 'James', 2, 24, 'نو تاسو وینئ چې انسان یوازې په ایمان نه بلکې په خپل عمل باندې نېک کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_24.mp3', '', 1761754199, 1761754199),
(30834, 'James 2:25', 'James', 2, 25, 'نو په همدې ډول بدلمنه راحاب د خپلو نېکو عملونو په وسیله چې اسراییلي استازو ته یې پناه ورکړه او د هغوی سره یې مرسته وکړه چې په بله لاره وتښتي، نېکه وګڼل شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_25.mp3', '', 1761754199, 1761754199),
(30835, 'James 2:26', 'James', 2, 26, 'نو لکه څنګه چې بدن بې له روح نه مړ دی، نو همدا شان ایمان هم بې له عمل نه مړ دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_26.mp3', '', 1761754199, 1761754199),
(30836, 'John 13:1', 'John', 13, 1, 'د فسحې د اختر نه یوه ورځ مخکې ؤ چې عیسی په دې پوه شو چې هغه وخت راورسېد چې د دې نړۍ نه لاړ شي او پلار ته ورشي. هغه د خپلو پیروانو سره چې د دې نړۍ سره یې تړاو درلود، مینه کوله او تر اخره پورې یې د هغوی سره مینه وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_1.mp3', '', 1761754199, 1761754199),
(30837, 'John 13:2', 'John', 13, 2, 'د ماښام د ډوډۍ وخت ؤ او شیطان له مخکې نه د شمعون اسخریوتي د زوی یهودا په زړه کې دا فکر اچولی ؤ چې د عیسی سره خیانت وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_2.mp3', '', 1761754199, 1761754199),
(30838, 'John 13:3', 'John', 13, 3, 'عیسی په دې پوهېده چې پلار ورته د ټولو شیانو اختیار ورکړی دی او هغه د خدای له خوا راغلی دی او بېرته خدای ته ورځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_3.mp3', '', 1761754199, 1761754199),
(30839, 'John 13:4', 'John', 13, 4, 'نو هغه د ډوډۍ نه راپاڅېده، خپله چپنه یې لېرې کړله او یو دستمال یې راواخیست او د خپلې ملا نه یې راتاو کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_4.mp3', '', 1761754199, 1761754199),
(30840, 'John 13:5', 'John', 13, 5, 'بیا یې په لګن کې اوبه واچولې او د خپلو شاګردانو د پښو په وینځلو یې پیل وکړ او هغه یې په هغه دستمال باندې چې د خپلې ملا نه یې تاو کړی ؤ، وچې کړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_5.mp3', '', 1761754199, 1761754199),
(30841, 'John 13:6', 'John', 13, 6, 'هغه شمعون پطروس ته ورغی نو پطروس هغه ته وویل: «ای څښتنه، ایا ته غواړې چې زما پښې ووینځې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_6.mp3', '', 1761754199, 1761754199),
(30842, 'John 13:7', 'John', 13, 7, 'عیسی په ځواب کې وویل: «ته اوس نه پوهېږې چې زه څه کوم، خو وروسته به پوه شې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_7.mp3', '', 1761754199, 1761754199),
(30843, 'John 13:8', 'John', 13, 8, 'پطروس ورته وویل: «ته به هېڅکله هم زما پښې نه وینځې.» عیسی وویل: «که زه ستا پښې ونه وینځم، نو ته به نور زما سره ملګرتیا ونه لرې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_8.mp3', '', 1761754199, 1761754199),
(30844, 'John 13:9', 'John', 13, 9, 'شمعون پطروس وویل: «بیا نو څښتنه، یوازې پښې مې نه بلکې لاسونه او سر مې هم ووینځه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_9.mp3', '', 1761754199, 1761754199),
(30845, 'John 13:10', 'John', 13, 10, 'عیسی ورته وویل: «چا چې ځان وینځلی وي نو هغه بیخي پاک وي او وینځلو ته اړتیا نه لري، یوازې پښې یې باید ووینځل شي. تاسو ټول پاک یئ، خو په تاسو کې یو کس پاک نه دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_10.mp3', '', 1761754199, 1761754199),
(30846, 'John 13:11', 'John', 13, 11, 'ځکه چې عیسی ته معلومه وه چې څوک به ورسره خیانت کوي، نو ځکه یې وویل: «تاسو ټول پاک یئ پرته د یو کس نه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_11.mp3', '', 1761754199, 1761754199),
(30847, 'John 13:12', 'John', 13, 12, 'کله چې عیسی د هغوی پښې ووینځلې، نو خپله چپنه یې بېرته واغوستله او بېرته دسترخوان ته کښېناست او د هغوی نه یې پوښتنه وکړه: «ما چې ستاسو دپاره څه وکړل ایا تاسو د هغې په معنی باندې پوه شوئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_12.mp3', '', 1761754199, 1761754199),
(30848, 'John 13:13', 'John', 13, 13, 'تاسو ماته استاذ او بادار وایئ او تاسو ښه کوئ چې داسې وایئ، ځکه چې زه همداسې یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_13.mp3', '', 1761754199, 1761754199),
(30849, 'John 13:14', 'John', 13, 14, 'که چېرې ما چې ستاسو بادار او استاذ یم ستاسو پښې ووینځلې، نو تاسو هم باید د یو بل پښې ووینځئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_14.mp3', '', 1761754199, 1761754199),
(30850, 'John 13:15', 'John', 13, 15, 'ما تاسو ته یو مثال درکړ، ترڅو تاسو د یو بل سره همداسې وکړئ لکه څنګه چې ما ستاسو دپاره وکړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_15.mp3', '', 1761754199, 1761754199),
(30851, 'John 13:16', 'John', 13, 16, 'په یقین سره زه تاسو ته دا وایم چې هېڅ یو نوکر د خپل بادار څخه لوی نه دی او هېڅ یو استازی د خپل رالېږونکي څخه لوی نه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_16.mp3', '', 1761754199, 1761754199),
(30852, 'John 13:17', 'John', 13, 17, 'اوس چې تاسو په دې شیانو باندې پوه شوئ، نو که عمل ورباندې وکړئ، نو تاسو بختور یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_17.mp3', '', 1761754199, 1761754199),
(30853, 'John 13:18', 'John', 13, 18, 'زه ستاسو ټولو په هکله خبرې نه کوم، کوم خلک چې ما غوره کړي دي زه هغوی پېژنم. خو د خدای د کلام دا وینا باید رښتیا شي چې وایي: ‹هغه چا چې زما سره یې ډوډۍ خوړله زما په ضد راپورته شو.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_18.mp3', '', 1761754199, 1761754199),
(30854, 'John 13:19', 'John', 13, 19, 'اوس زه تاسو ته د هغې پېښې د رامنځته کېدلو نه مخکې وایم، د دې دپاره کله چې هغه پېښه وشي، نو تاسو به په دې ایمان راوړئ چې زه هماغه یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_19.mp3', '', 1761754199, 1761754199),
(30855, 'John 13:20', 'John', 13, 20, 'په یقین سره زه تاسو ته دا وایم څوک چې هغه کس قبول کړي چې زه یې لېږم، نو زه یې قبول کړی یم او هرڅوک چې ما قبول کړي، نو هغه څوک یې قبول کړی چې زه یې رالېږلی یم.» د یهودا د خیانت په هکله د عیسی پېشګویي (متي ۲۶‏:‌۲۰‌‏-‌۲۵ او مرقوس ۱۴‏:‌۱۷‌‏-‌۲۱ او لوقا ۲۲‏:‌۲۱‌‏-‌۲۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_20.mp3', '', 1761754199, 1761754199),
(30856, 'John 13:21', 'John', 13, 21, 'کله چې عیسی دا خبرې وکړې، نو د هغه روح نا‌ارامه شو او په ښکاره یې وویل: «په یقین سره زه تاسو ته دا وایم چې په تاسو کې به یو کس زما سره خیانت وکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_21.mp3', '', 1761754199, 1761754199),
(30857, 'John 13:22', 'John', 13, 22, 'شاګردانو یو بل ته وکتل او شکمن شول چې هغه د چا په هکله خبرې کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john13_verse_22.mp3', '', 1761754199, 1761754199),
