(30894, 'Matthew 6:21', 'Matthew', 6, 21, 'ځکه په هرځای کې چې ستا خزانه وي نو هلته به ستا زړه هم وي. د بدن څراغ (لوقا ۱۱‏:‌۳۴‌‏-‌۳۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_21.mp3', '', 1761754199, 1761754199),
(30895, 'Matthew 6:22', 'Matthew', 6, 22, 'سترګې د بدن څراغ دی. که سترګې دې روغې وي، نو ټول بدن به دې روښانه وي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_22.mp3', '', 1761754199, 1761754199),
(30896, 'Matthew 6:23', 'Matthew', 6, 23, 'خو که سترګې دې روغې نه وي، نو ټول بدن به دې په تیاره کې وي. که چېرې هغه رڼا چې په تا کې ده هغه تیاره شي، نو دا به څومره لویه تیاره وي! خدای او شتمني (لوقا ۱۶‏:‌۱۳، ۱۲‏:‌۲۲‌‏-‌۳۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_23.mp3', '', 1761754199, 1761754199),
(30897, 'Matthew 6:24', 'Matthew', 6, 24, 'هېڅوک نه شي کولای چې د دوو بادارانو خدمت وکړي، ځکه چې یا خو به د یو څخه کرکه کوي او د بل سره مینه او یا به یو ته وفادار وي او بل ته به په بده سترګه ګوري. تاسو نه شئ کولای چې هم د خدای بندګي وکړئ او هم د پیسو. اندېښنه مه کوئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_24.mp3', '', 1761754199, 1761754199),
(30898, 'Matthew 6:25', 'Matthew', 6, 25, 'نو له دې امله تاسو ته وایم چې د خپل ژوند دپاره اندېښنه مه کوئ چې څه به خورئ او څه به څښئ او نه د خپل بدن په هکله چې څه شی به اغوندئ. ایا ژوند د خوراک څخه او بدن د کالیو څخه مهم نه دی؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_25.mp3', '', 1761754199, 1761754199),
(30899, 'Matthew 6:26', 'Matthew', 6, 26, 'د هوا مرغانو ته وګورئ. هغوی نه څه کري او نه څه رېبي او نه څه په ګودامونو کې ذخیره کوي، خو بیاهم ستاسو اسماني پلار هغوی ته روزي رسوي. ایا تاسو د هغو څخه ډېر ارزښت نه لرئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_26.mp3', '', 1761754199, 1761754199),
(30900, 'Matthew 6:27', 'Matthew', 6, 27, 'ایا په تاسو کې څوک کولای شي چې په اندېښنو سره د خپل عمر یو ساعت هم زیات کړي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_27.mp3', '', 1761754199, 1761754199),
(30901, 'Matthew 6:28', 'Matthew', 6, 28, 'نو بیا ولې د خپلو کالیو دپاره اندېښنه کوئ؟ ځنګلي ګلانو ته وګورئ چې څنګه لوییږي. هغوی نه کار کوي او نه د ځان دپاره کالي جوړوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_28.mp3', '', 1761754199, 1761754199),
(30902, 'Matthew 6:29', 'Matthew', 6, 29, 'بیاهم زه تاسو ته وایم چې حتی سلیمان پاچا هم د خپل ټول شان او شوکت سره د دې ګلانو په شان ښکلي کالي نه وو اغوستي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_29.mp3', '', 1761754199, 1761754199),
(30903, 'Matthew 6:30', 'Matthew', 6, 30, 'خو که چېرې خدای د صحرا واښو ته چې نن دلته دي او سبا په تنور کې اچول کیږي داسې کالي ورکولای شي، ایا هغه به تاسو ته د هغو څخه ښه کالي در نه کړي؟ ستاسو ایمان ولې دومره کمزوری دی؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_30.mp3', '', 1761754199, 1761754199),
(30904, 'Matthew 6:31', 'Matthew', 6, 31, 'نو اندېښنه مه کوئ او مه وایئ: ‹مونږ به څه خورو؟ څه به څښو؟ او څه به اغوندو؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_31.mp3', '', 1761754199, 1761754199),
(30905, 'Matthew 6:32', 'Matthew', 6, 32, 'ځکه چې بې‌ایمانه خلک د دې ټولو شیانو په هکله اندېښنه کوي، خو ستاسو اسماني پلار پوهیږي چې تاسو دې ټولو شیانو ته اړتیا لرئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_32.mp3', '', 1761754199, 1761754199),
(30906, 'Matthew 6:33', 'Matthew', 6, 33, 'خو د هرڅه نه لومړی د خدای پاچاهي او د هغه عدالت وغواړئ، نو بیا به دا ټول شیان هم تاسو ته درکړل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_33.mp3', '', 1761754199, 1761754199),
(30907, 'Matthew 6:34', 'Matthew', 6, 34, 'نو د سبا دپاره اندېښنه مه کوئ، ځکه چې د سبا اندېښنې د سبا دپاره دي. د نن ورځې ستونزې د نن دپاره بس دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew6_verse_34.mp3', '', 1761754199, 1761754199),
(30908, 'Hebrews 6:1', 'Hebrews', 6, 1, 'نو راځئ چې د مسیح په هکله لومړنی تعلیم پرېږدو او د کاملتوب خواته لاړ شو. د دې اړتیا نشته چې مونږ دې بیا بیا هغه لومړني تعلیمونه تکرار کړو لکه د بدو کارونو نه توبه ویستل او په خدای باندې ایمان راوړل،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_1.mp3', '', 1761754199, 1761754199),
(30909, 'Hebrews 6:2', 'Hebrews', 6, 2, 'د تعمید د غسلونو تعلیم او په سر د لاس ایښودلو تعلیم، د مړو نه د بیا راژوندي کېدلو او تلپاتې قضاوت په هکله تعلیم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_2.mp3', '', 1761754199, 1761754199),
(30910, 'Hebrews 6:3', 'Hebrews', 6, 3, 'که د خدای رضا وي، نو مونږ به همدا کارونه کوو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_3.mp3', '', 1761754199, 1761754199);